class SwatchRenderer extends JLabel implements ListCellRenderer<Color> {
    public Component getListCellRendererComponent(
            JList<? extends Color> list, Color value, int index,
            boolean isSelected, boolean cellHasFocus) {
        setOpaque(true);
        setBackground(value);                    // caller decides the visuals
        setText(value == null ? "" : "rgb " + value.getRGB());
        return this;                             // painted as the cell
    }
}
